#!/usr/bin/env python3
"""Calculate mean price from housing dataset, ignoring missing values."""

import csv

def calculate_mean_price(filepath):
    """Read CSV and calculate mean price excluding missing values."""
    prices = []

    with open(filepath, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            price_str = row.get('price', '').strip()
            if price_str and price_str != '':
                try:
                    price = float(price_str)
                    prices.append(price)
                except ValueError:
                    # Skip rows with non-numeric prices
                    continue

    if len(prices) == 0:
        return None

    mean_price = sum(prices) / len(prices)
    return mean_price

if __name__ == '__main__':
    filepath = 'data/housing_dataset.csv'
    mean = calculate_mean_price(filepath)

    if mean is not None:
        rounded_mean = round(mean, 2)
        print(f"@mean_price[{rounded_mean}]")
    else:
        print("No valid prices found in dataset")
